VALUES ('cao-cao', '曹操', ARRAY[]::text[], NULL, NULL, 155, 1, NULL, 'year', 220, 3, NULL, 'month', ARRAY['政治家','军事家','文学家'], '东汉末权臣，魏武帝（追尊），官渡之战主将。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹操"}]'::jsonb, NULL, NULL, NULL)
