VALUES ('cao-pi', '曹丕', ARRAY[]::text[], NULL, NULL, 187, 1, NULL, 'year', 226, 6, NULL, 'month', ARRAY['皇帝'], '曹操之子，承袭魏王后于220年受汉献帝禅让称帝，建立曹魏，在位至226年。他延续父亲奠定的北方政权，并以九品中正制等措施整顿选官；其子曹叡继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹丕"}]'::jsonb, '文皇帝', '高祖', '魏文帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('cao-rui', '曹叡', ARRAY[]::text[], NULL, NULL, 206, 1, NULL, 'year', 239, 1, NULL, 'year', ARRAY['皇帝'], '曹丕之子，226—239年在位，是曹魏第二帝。即位后面对蜀汉、孙吴的持续攻势，主持防御与政务；因无亲生子，临终托孤并立养子曹芳为帝，由曹爽、司马懿辅政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹叡"}]'::jsonb, '明皇帝', '烈祖', '魏明帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-bei', '刘备', ARRAY[]::text[], NULL, NULL, 161, 1, NULL, 'year', 223, 6, NULL, 'month', ARRAY['皇帝'], '汉景帝之子中山靖王刘胜之后，长期辗转于群雄之间，后据有益州。221年在成都称帝、国号汉，史称蜀汉；次年为报关羽之仇伐吴，夷陵之战败后退守永安，223年去世并由刘禅继位。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘备"}]'::jsonb, '昭烈皇帝', '烈祖', '昭烈帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-shan', '刘禅', ARRAY[]::text[], NULL, NULL, 207, 1, NULL, 'year', 271, 1, NULL, 'year', ARRAY['皇帝'], '刘备之子，223年继位，在位至263年，是蜀汉第二帝。刘备去世后由诸葛亮辅政，诸葛亮及其后蒋琬、费祎、姜维等先后主持国政；263年魏军攻入蜀地，刘禅向邓艾投降，蜀汉灭亡。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘禅"}]'::jsonb, '孝怀皇帝', NULL, '蜀汉后主')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('sun-quan', '孙权', ARRAY[]::text[], NULL, NULL, 182, 7, NULL, 'month', 252, 5, NULL, 'month', ARRAY['皇帝'], '孙坚之子、孙策之弟，承接孙策经营的江东基业，逐步确立对长江中下游及岭南部分地区的统治。208年与刘备结盟，在赤壁之战中击退曹操；222年受封吴王，229年称帝，在位至252年，孙吴由其子孙继续统治。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙权"}]'::jsonb, '大皇帝', '太祖', '大皇帝')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhuge-liang', '诸葛亮', ARRAY[]::text[], NULL, NULL, 181, 1, NULL, 'year', 234, 8, NULL, 'month', ARRAY['政治家','军事家'], '三国蜀汉政治家、军事家，字孔明，琅邪阳都人。刘备三顾茅庐后出仕，辅佐建立蜀汉并任丞相；刘备死后主持朝政，多次北伐曹魏，卒于五丈原。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/诸葛亮"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('zhou-yu', '周瑜', ARRAY[]::text[], NULL, NULL, 175, 1, NULL, 'year', 210, 1, NULL, 'year', ARRAY['军事家'], '东汉末孙吴将领，字公瑾，庐江舒人。辅佐孙策平定江东，孙权时任水军统帅；208年赤壁之战与刘备联军击败曹操军，后筹划攻取益州，病逝于巴丘。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周瑜"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('deng-ai', '邓艾', ARRAY[]::text[], NULL, NULL, 197, 1, NULL, 'year', 264, 1, NULL, 'year', ARRAY['军事家','将领'], '曹魏将领，景元四年率军由阴平道奇袭江油，参与灭蜀之战；钟会诬告邓艾谋反并将其囚禁，钟会兵变失败后邓艾在押送途中被杀。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓艾"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('yuan-shao', '袁绍', ARRAY[]::text[], NULL, NULL, 154, 1, NULL, 'year', 202, 6, NULL, 'month', ARRAY['军阀'], '东汉末军阀，字本初，汝南汝阳人，出身汝南袁氏。董卓乱政后参与关东联军，控制冀、青、并等州；官渡之战败于曹操，202年病逝，袁氏势力随后瓦解。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁绍"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
INSERT INTO persons (id, name, alt_names, ancestral_xing, clan_shi, birth_year, birth_month, birth_day, birth_confidence, death_year, death_month, death_day, death_confidence, roles, bio, links, posthumous_name, temple_name, title)
VALUES ('liu-zhang', '刘璋', ARRAY[]::text[], NULL, NULL, 176, 1, NULL, 'year', 219, 1, NULL, 'year', ARRAY['军阀'], '益州牧，刘焉之子；引刘备入蜀后失益州，东汉末地方势力；投降后被刘备迁往公安并封振威将军；刘备接管益州后建立蜀汉政权。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘璋"}]'::jsonb, NULL, NULL, NULL)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;

